def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Restore the two-color frame around the patterned interior.
    for r in range(h):
        for c in range(w):
            if r < 2 or c < 2:
                if grid[r][c] == 0:
                    out[r][c] = 1
            elif r == 2 or c == 2:
                if grid[r][c] == 0:
                    out[r][c] = 4

    # Find the pattern's period from intact portions of the interior rows.
    period = 5
    for p in range(2, 10):
        valid = True
        for r in range(3, h):
            phases = {}
            for c in range(6, w):
                v = grid[r][c]
                if v:
                    if c % p in phases and phases[c % p] != v:
                        valid = False
                        break
                    phases[c % p] = v
            if not valid:
                break
        if valid:
            period = p
            break

    # Extend each row's observed pattern through the masked cells.
    for r in range(3, h):
        phases = {}
        for c in range(6, w):
            v = grid[r][c]
            if v:
                phases[c % period] = v
        for c in range(3, w):
            if grid[r][c] == 0 and c % period in phases:
                out[r][c] = phases[c % period]

    return out
